# KasKorsou Deploy Script - Decodes and creates all missing component files
$ErrorActionPreference = "Stop"
$base = "C:\Users\peter\Desktop\KasKorsou-web\src"

# Ensure directories exist
New-Item -ItemType Directory -Force -Path "$base\components" | Out-Null
New-Item -ItemType Directory -Force -Path "$base\pages" | Out-Null

Write-Host "Deploying KasKorsou components..." -ForegroundColor Cyan

# ListingCard.jsx
$b64 = ""
[System.IO.File]::WriteAllBytes("$base\components\ListingCard.jsx", [Convert]::FromBase64String($b64))
Write-Host "  ListingCard.jsx" -ForegroundColor Green
# FilterSidebar.jsx
$b64 = ""
[System.IO.File]::WriteAllBytes("$base\components\FilterSidebar.jsx", [Convert]::FromBase64String($b64))
Write-Host "  FilterSidebar.jsx" -ForegroundColor Green
# MapView.jsx
$b64 = ""
[System.IO.File]::WriteAllBytes("$base\components\MapView.jsx", [Convert]::FromBase64String($b64))
Write-Host "  MapView.jsx" -ForegroundColor Green
# DetailPage.jsx
$b64 = ""
[System.IO.File]::WriteAllBytes("$base\pages\DetailPage.jsx", [Convert]::FromBase64String($b64))
Write-Host "  DetailPage.jsx" -ForegroundColor Green

Write-Host ""
Write-Host "Alle 4 bestanden succesvol aangemaakt!" -ForegroundColor Green
Write-Host "Klaar voor npm install + npm run dev" -ForegroundColor Cyan